record PagedResult<T>(List<T> Items, int Page, int Size, int Total)
{
    public int TotalPages => (int)Math.Ceiling(Total / (double)Size);
}

static class Paged
{
    public static PagedResult<T> Create<T>(List<T> all, int page, int size)
    {
        size = Math.Clamp(size, 1, 10);
        page = Math.Max(1, page);
        return new(all.Skip((page - 1) * size).Take(size).ToList(), page, size, all.Count);
    }
}

