IEnumerable<Product> Search(string? category, decimal? maxPrice, string? q)
{
    IEnumerable<Product> query = products;
    if (!string.IsNullOrWhiteSpace(category)) query = query.Where(p => p.Category == category);
    if (maxPrice is not null) query = query.Where(p => p.Price <= maxPrice);
    if (!string.IsNullOrWhiteSpace(q)) query = query.Where(p => p.Name.Contains(q, StringComparison.OrdinalIgnoreCase));
    return query;
}

